"""Build portable, offline HTML viewers from measured MATLAB/Simulink results."""
from pathlib import Path
import csv, json, html
ROOT=Path(__file__).resolve().parents[1]
def rows(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
STYLE='''*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#172b42;font:16px/1.55 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:42px 28px}header{margin-bottom:30px}.eyebrow{color:#41628a;font-size:12px;font-weight:800;letter-spacing:2px}h1{font-size:clamp(32px,5vw,54px);line-height:1.1;margin:12px 0}h2{font-size:20px;margin:0 0 14px}.intro{max-width:850px;color:#53677f}a{color:#006cb6}.badge{display:inline-block;background:#dcece8;border:1px solid #b4d8cd;color:#17634b;border-radius:20px;padding:4px 12px;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border:1px solid #dce3eb;border-radius:15px;padding:24px;margin-bottom:20px;box-shadow:0 4px 16px #172b4205}.metric{font-size:32px;font-weight:750}.muted,small{color:#64748b}.controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap}input[type=range]{flex:1;min-width:150px;accent-color:#007ea5}select,button{font:inherit;background:#f8fafc;border:1px solid #bac8d6;border-radius:8px;padding:8px 14px}button{cursor:pointer;background:#133953;color:white}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #28b5d5;outline-offset:3px}svg{display:block;width:100%;height:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid #e3e9ef}th{color:#5d728b;font-size:12px;text-transform:uppercase}.note{border-left:4px solid #d49a28;padding:12px 18px;background:#fff8e8;font-size:14px}.flex{display:grid;grid-template-columns:1.4fr 1fr;gap:20px}footer{font-size:13px;color:#64748b;padding:15px 0}.scroll{overflow-x:auto}@media(max-width:700px){main{padding:24px 14px}.grid,.flex{grid-template-columns:1fr}h1{font-size:34px}.card{padding:18px}}'''
def page(title,content,script):
    return '<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+'</title><style>'+STYLE+'</style><main>'+content+'<footer>Portfolio de Alejandro Pedersen · Código MIT · Creación asistida por IA · Resultados reproducibles, sin afirmación de despliegue industrial.</footer></main><script>'+script+'</script></html>'

s=ROOT; summary=json.loads((s/'results/summary.json').read_text()); reports=summary['results']; traces={}
for r in reports:
    raw=rows(s/'results'/f'{r["scenario"]}.csv');traces[r['scenario']]=[{k:float(v) for k,v in row.items()} for row in raw]
nom=next(r for r in reports if r['scenario']=='nominal');em=next(r for r in reports if r['scenario']=='emergency_stop')
content='''<header><div class="eyebrow">PROYECTO 02 / SIMULINK / LÍNEAS AUTOMATIZADAS</div><h1>Servo Transfer Cell</h1><p class="intro">Puesta en marcha virtual de una estación de transferencia. Reproduce el movimiento, la secuencia y los interbloqueos a partir de trazas del solver de Simulink.</p><span class="badge">Simulación real ejecutada · Modelo reconstruible desde código</span></header>
<section class="grid"><div class="card"><div class="muted">Escenarios aprobados</div><div class="metric">'''+str(len(reports))+''' / '''+str(len(reports))+'''</div><small>Operación, perturbaciones e inyección de fallos</small></div><div class="card"><div class="muted">Ciclo nominal medido</div><div class="metric">'''+f'{nom["cycleTime"]:.2f}'+''' s</div><small>Desde inicio hasta retorno completado</small></div><div class="card"><div class="muted">Distancia de parada simulada</div><div class="metric">'''+f'{em["stopDistance"]*1000:.1f}'+''' mm</div><small>Modelo de freno idealizado; no validación de seguridad</small></div></section>
<section class="card"><h2>Reproduce una prueba</h2><div class="controls"><label for="scenario">Escenario</label><select id="scenario">'''+''.join(f'<option value="{r["scenario"]}">{r["scenario"].replace("_"," ")}</option>' for r in reports)+'''</select><button id="play">Reproducir</button><label for="time">Tiempo</label><input id="time" type="range" min="0" max="1600" value="0" step="1"><output id="clock">0.00 s</output></div>
<svg viewBox="0 0 1000 235" role="img" aria-label="Posición del carro de transferencia"><rect x="75" y="125" width="850" height="20" rx="6" fill="#dce4ed"/><line x1="100" y1="135" x2="880" y2="135" stroke="#69829a" stroke-width="3"/><rect x="719" y="30" width="140" height="65" rx="9" fill="#e8eff7" stroke="#90a7c0"/><text x="789" y="65" text-anchor="middle" font-size="16" fill="#244763">Estación de trabajo</text><line x1="789" y1="100" x2="789" y2="160" stroke="#a7b9cd" stroke-dasharray="5 5"/><text x="126" y="185" font-size="15" fill="#526980">Origen · 0 m</text><text x="731" y="185" font-size="15" fill="#526980">Objetivo · 0.65 m</text><g id="carriage"><rect x="-31" y="90" width="62" height="34" rx="7" fill="#007ea5"/><rect x="-17" y="68" width="34" height="22" rx="3" fill="#e4b85b"/><circle cx="-19" cy="126" r="7" fill="#17364f"/><circle cx="19" cy="126" r="7" fill="#17364f"/></g></svg>
<div class="grid"><div><small>Estado</small><div id="state" class="metric"></div></div><div><small>Velocidad / fuerza</small><div id="motion"></div></div><div><small>Alarma / ciclos</small><div id="alarm"></div></div></div><svg id="trace" viewBox="0 0 1000 240" role="img" aria-label="Traza de posición y cursor de tiempo"></svg></section>
<section class="card"><h2>Evidencia de aceptación</h2><div class="scroll"><table><thead><tr><th>Escenario</th><th>Resultado</th><th>Ciclos</th><th>Alarma final</th></tr></thead><tbody>'''+''.join(f'<tr><td>{r["scenario"].replace("_"," ")}</td><td>PASS</td><td>{r["cycles"]}</td><td>{r["finalAlarm"]}</td></tr>' for r in reports)+'''</tbody></table></div><p><a href="../README.md">README</a> · <a href="../results/acceptance.csv">Resultados CSV</a> · <a href="requirements.md">Requisitos</a> · <a href="defensa-es.md">Guía de entrevista</a></p></section><p class="note">Esta animación reproduce datos ya simulados; no controla hardware. No existe conexión a PLC ni robot y la parada de emergencia representada no es una función de seguridad certificada.</p>'''
script='const traces='+json.dumps(traces,separators=(',',':'))+''';const names=['IDLE','INDEX','PROCESS','RETURN','COMPLETE','FAULT','MANUAL'];const choice=document.getElementById('scenario'),slider=document.getElementById('time'),play=document.getElementById('play');let running=false,previous=null,fractional=0;function update(){const d=traces[choice.value];slider.max=d.length-1;const i=Math.min(+slider.value,d.length-1),r=d[i];document.getElementById('clock').textContent=r.time.toFixed(2)+' s';document.getElementById('state').textContent=names[Math.round(r.state)];document.getElementById('state').style.color=r.state===5?'#b33e55':'#007ea5';document.getElementById('motion').textContent=r.velocity.toFixed(3)+' m/s · '+r.force.toFixed(1)+' N';document.getElementById('alarm').textContent='Código '+r.alarm+' · '+r.cycles+' ciclo(s)';document.getElementById('carriage').setAttribute('transform','translate('+(160+r.position*968)+',0)');let pts=d.filter((_,k)=>k%4===0).map(a=>(55+a.time*56.5)+','+(185-a.position*200)).join(' ');let cursor=55+r.time*56.5;document.getElementById('trace').innerHTML='<line x1="55" y1="185" x2="960" y2="185" stroke="#cbd5e1"/><line x1="55" y1="55" x2="960" y2="55" stroke="#dbe3ed" stroke-dasharray="5 5"/><text x="5" y="60" font-size="13" fill="#64748b">0.65 m</text><text x="20" y="190" font-size="13" fill="#64748b">0</text><polyline points="'+pts+'" fill="none" stroke="#007ea5" stroke-width="2.5"/><line x1="'+cursor+'" y1="25" x2="'+cursor+'" y2="200" stroke="#d58d34" stroke-width="2"/><text x="55" y="228" font-size="13" fill="#64748b">Posición medida · 0–16 segundos</text>'}function tick(now){if(running){if(previous!==null){const next=+slider.value+fractional+(now-previous)/10;fractional=next-Math.floor(next);slider.value=Math.min(+slider.max,Math.floor(next));update();if(+slider.value>=+slider.max){running=false;play.textContent='Reproducir'}}previous=now}else previous=null;requestAnimationFrame(tick)}play.onclick=()=>{if(+slider.value>=+slider.max)slider.value=0;running=!running;play.textContent=running?'Pausar':'Reproducir'};choice.onchange=()=>{slider.value=0;running=false;play.textContent='Reproducir';update()};slider.oninput=update;update();requestAnimationFrame(tick);'''
(s/'docs/demo.html').write_text(page('Servo Transfer Cell — demo',content,script),encoding='utf-8')

print("Offline viewer generated from results.")
